import{getProductById as t}from"../data.js";import{formatPrice as n}from"../format.js";import{addToCart as a}from"../store.js";export function renderProduct(e,d){const o=t(d.id);if(!o)return void(e.innerHTML='\n      <section class="not-found">\n        <h1>Product not found</h1>\n        <p><a href="#/">Back to the catalog</a></p>\n      </section>\n    ');e.innerHTML=`\n    <a class="back-link" href="#/">&larr; Back to catalog</a>\n    <section class="product-detail">\n      <div class="product-detail-media">\n        <img src="${o.image}" alt="${o.name}" width="600" height="450" decoding="async">\n      </div>\n      <div class="product-detail-body">\n        <p class="eyebrow">${o.category}</p>\n        <h1>${o.name}</h1>\n        <p class="product-detail-price">${n(o.price)}</p>\n        <p class="product-detail-rating">★ ${o.rating.toFixed(1)} / 5</p>\n        <p class="product-detail-desc">${o.description}</p>\n\n        <div class="qty-row">\n          <label for="qty">Quantity</label>\n          <input type="number" id="qty" min="1" value="1" inputmode="numeric">\n        </div>\n\n        <button type="button" class="btn btn-solid" id="add-btn">Add to cart</button>\n        <p id="add-status" class="add-status" role="status" aria-live="polite"></p>\n      </div>\n    </section>\n  `;const i=e.querySelector("#qty"),r=e.querySelector("#add-btn"),s=e.querySelector("#add-status");r.addEventListener("click",()=>{const t=Math.max(1,parseInt(i.value,10)||1);a(o.id,t),s.textContent=`Added ${t} to cart.`})}